import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int left = Math.min(n, 5);
        int right = Math.max(0, n - 5);

        StringBuilder sb = new StringBuilder();
        appendHand(sb, left);
        sb.append('\n');
        appendHand(sb, right);

        System.out.print(sb.toString());
    }

    private static void appendHand(StringBuilder sb, int fingers) {
        if (fingers == 0) {
            sb.append('*');
        } else {
            for (int i = 0; i < fingers; i++) {
                sb.append('I');
            }
        }
    }
}
